#!/usr/bin/env bash
# Prepares a release: stamps the integrity of the prebuilt archives in dist/
# into dnfo/private/versions.bzl, creates the source archive used by
# the Bazel Central Registry and prints the release notes.
#
# Usage: .github/workflows/release_prep.sh <tag> [dist dir]
set -o errexit -o nounset -o pipefail

TAG=$1
DIST=${2:-}
VERSION=${TAG#v}
PREFIX="rules_dnfo-${VERSION}"
ARCHIVE="rules_dnfo-${TAG}.tar.gz"

work=$(mktemp -d)
trap 'rm -rf "$work"' EXIT
git archive --format=tar --prefix="${PREFIX}/" "${TAG}" | tar -x -C "$work"

# Stamp the module version.
sed -i.bak "0,/version = \".*\"/s//version = \"${VERSION}\"/" "$work/$PREFIX/MODULE.bazel"
rm -f "$work/$PREFIX/MODULE.bazel.bak"

# If dist directory is provided, stamp integrity into versions.bzl
if [[ -n "$DIST" && -d "$DIST" ]]; then
    DIST=$(realpath "$DIST")
    PLATFORMS=$(sed -n 's/^    "\([a-z0-9_]*\)": \[$/\1/p' dnfo/private/platforms.bzl)
    integrity=""
    for platform in $PLATFORMS; do
        file="$DIST/dnfo-${VERSION}-${platform}.tar.gz"
        if [[ ! -f "$file" ]]; then
            echo "ERROR: Missing distribution archive for platform '$platform': $file" >&2
            exit 1
        fi
        sri="sha256-$(openssl dgst -sha256 -binary "$file" | base64)"
        integrity+="    \"${platform}\": \"${sri}\",\n"
    done

    cat > "$work/$PREFIX/dnfo/private/versions.bzl" <<EOF
"""Prebuilt dnfo release (generated by .github/workflows/release_prep.sh)."""

VERSION = "${VERSION}"

RELEASE_URL_TEMPLATE = "https://github.com/bookingcom/rules_dnfo/releases/download/v{version}/dnfo-{version}-{platform}.tar.gz"

INTEGRITY = {
$(printf '%b' "$integrity")}
EOF

    dist_bzl="$work/$PREFIX/cmd/dnfo/dist.bzl"
    if [[ -f "$dist_bzl" ]]; then
        sed -i.bak -E 's/DEFAULT_VERSION = "[^"]*"/DEFAULT_VERSION = "'"${VERSION}"'"/' "$dist_bzl"
        rm -f "$dist_bzl.bak"
    fi
fi

tar --sort=name --owner=0 --group=0 --numeric-owner --mtime="@0" -C "$work" -cf - "$PREFIX" | gzip -n >"$ARCHIVE"

cat <<NOTES
# rules_dnfo ${VERSION}

## Using Bzlmod

Add to your \`MODULE.bazel\`:

\`\`\`starlark
bazel_dep(name = "rules_dnfo", version = "${VERSION}")

dnfo = use_extension("@rules_dnfo//dnfo:extensions.bzl", "dnfo")
dnfo.toolchains()
use_repo(dnfo, "dnfo_toolchains")

register_toolchains("@dnfo_toolchains//:all")
\`\`\`

### Example

\`\`\`starlark
load("@rules_dnfo//dnfo:defs.bzl", "dnfo_image")

dnfo_image(
    name = "my_image",
    config = "dnfo.yaml",
    architecture = "x86_64",
    output = "oci",
)
\`\`\`
NOTES
